END
DISABLE WebAutomation.LaunchChrome.AttachToForegroundChrome AttachTimeout: 5 TargetDesktop: $'''{\"DisplayName\":\"Ordinateur local\",\"Route\":{\"ServerType\":\"Local\",\"ServerAddress\":\"\"},\"DesktopType\":\"local\"}''' BrowserInstance=> Browser
IF varEntree_EtapeReaffectation = $'''True''' THEN
 CALL 'Reaffectation Dossier'
END
EXIT Code: 0
FUNCTION 'Sign-In' GLOBAL
 /# A modifier si nécessaire : 
- Les boites de dialogues s'ouvrent sur l'ordinateur RPA: il serait peut-être préférable de demander les informations de connexion au niveau du flux cloud ? Sécurisation nécessaire#/
 WebAutomation.GetDetailsOfWebPage BrowserInstance: Browser DetailsType: WebAutomation.DetailsType.URLAddress Details=> WebPageProperty_URL
 IF WebPageProperty_URL = $'''%varEntree_URLSolidiag%/login''' THEN
 SET varSortie_StatutConnexion TO $'''false'''
 EXIT Code: 0 ErrorMessage: $'''Le compte SOLIDIAG n\'est pas connecté'''
 ELSE
 SET varSortie_StatutConnexion TO $'''True'''
 END
 DISABLE IF (OCR.IfTextOnScreen.TextOnScreenExistsWithWindowsOcr TextToFind: $'''Liste des ménages''' IsRegex: False WindowsOcrLanguage: OCR.WindowsOcrLanguage.French SearchForTextOn: OCR.SearchTarget.ForegroundWindow ImageWidthMultiplier: 1 ImageHeightMultiplier: 1) THEN
 DISABLE SET varSortie_StatutConnexion TO $'''True'''
 DISABLE END
 IF varSortie_StatutConnexion <> $'''True''' THEN
 SET varSortie_StatutConnexion TO $'''false'''
 Display.InputDialog Title: $'''Sign-in SODIAG''' Message: $'''Veuillez rentrer votre nom d\'utilisateur SODIAG''' InputType: Display.InputType.SingleLine IsTopMost: False UserInput=> varUser_Sodiag
 Display.InputDialog Title: $'''Sign-in SODIAG''' Message: $'''Veuillez rentrer votre mot de passe''' InputType: Display.InputType.Password IsTopMost: False UserInput=> varMdp_Sodiag
 WebAutomation.PopulateTextField.PopulateTextFieldUsePhysicalKeyboard BrowserInstance: Browser Control: appmask['FormulaireSignIn']['Input_SignIn_User'] Text: varUser_Sodiag Mode: WebAutomation.PopulateTextMode.Replace UnfocusAfterPopulate: True WaitForPageToLoadTimeout: 60
 WebAutomation.PopulateTextField.PopulateTextFieldUsePhysicalKeyboard BrowserInstance: Browser Control: appmask['FormulaireSignIn']['Input_SignIn_MDP'] Text: varMdp_Sodiag Mode: WebAutomation.PopulateTextMode.Replace UnfocusAfterPopulate: True WaitForPageToLoadTimeout: 60
 WebAutomation.Click.Click BrowserInstance: Browser Control: appmask['FormulaireSignIn']['Case_SignIn_ConditionGenerales'] ClickType: WebAutomation.ClickType.LeftClick MouseClick: True WaitForPageToLoadTimeout: 60 MousePositionRelativeToElement: WebAutomation.RectangleEdgePoint.MiddleCenter OffsetX: 0 OffsetY: 0
 WebAutomation.Click.ClickCloseDialog BrowserInstance: Browser Control: appmask['FormulaireSignIn']['Bttn_SignIn_Connexion'] ClickType: WebAutomation.ClickType.LeftClick MouseClick: True WaitForPageToLoadTimeout: 60 MousePositionRelativeToElement: WebAutomation.RectangleEdgePoint.MiddleCenter OffsetX: 0 OffsetY: 0
 SET varSortie_StatutConnexion TO $'''true'''
 END
 EXIT FUNCTION
END FUNCTION
