FUNCTION 'Info de la Visite - Bati' GLOBAL
 WebAutomation.LaunchChrome.AttachToForegroundChrome AttachTimeout: 5 TargetDesktop: $'''{\"DisplayName\":\"Ordinateur local\",\"Route\":{\"ServerType\":\"Local\",\"ServerAddress\":\"\"},\"DesktopType\":\"local\"}''' BrowserInstance=> Browser
 UIAutomation.GetWindow.GetForegroundWindow WindowTitle=> WindowTitle WindowInstance=> AutomationWindow
 IF varEntree_TypeHabitat = $'''Individuel''' THEN
 WebAutomation.Click.Click BrowserInstance: Browser Control: appmask['FormulaireInfosVisite']['Case_InfosVisite_Typehabitat_Individuel'] ClickType: WebAutomation.ClickType.LeftClick MouseClick: True WaitForPageToLoadTimeout: 60 MousePositionRelativeToElement: WebAutomation.RectangleEdgePoint.MiddleCenter OffsetX: 0 OffsetY: 0
 ELSE
 WebAutomation.Click.Click BrowserInstance: Browser Control: appmask['FormulaireInfosVisite']['Case_InfosVisite_TypeHabitat_Collectif'] ClickType: WebAutomation.ClickType.LeftClick MouseClick: True WaitForPageToLoadTimeout: 60 MousePositionRelativeToElement: WebAutomation.RectangleEdgePoint.MiddleCenter OffsetX: 0 OffsetY: 0
 END
 WebAutomation.Click.Click BrowserInstance: Browser Control: appmask['FormulaireInfosVisite']['Dpdown_InfosVisite_AnneeConstruction'] ClickType: WebAutomation.ClickType.LeftClick MouseClick: True WaitForPageToLoadTimeout: 60 MousePositionRelativeToElement: WebAutomation.RectangleEdgePoint.MiddleCenter OffsetX: 0 OffsetY: 0
 Text.ToNumber Text: varEntree_AnneeConstruction Number=> varAnneeConstructionChiffre
 ON ERROR
 GOTO 'Année Construction non convertible en chiffre'
 END
 IF varAnneeConstructionChiffre <= 1949 THEN
 MouseAndKeyboard.SendKeys.FocusAndSendKeys TextToSend: $'''< 1949{Enter}''' DelayBetweenKeystrokes: 10 SendTextAsHardwareKeys: False
 ELSE IF varAnneeConstructionChiffre = (varAnneeConstructionChiffre >= 1950 AND varAnneeConstructionChiffre <= 1974) THEN
 MouseAndKeyboard.SendKeys.FocusAndSendKeys TextToSend: $'''1950-1974''' DelayBetweenKeystrokes: 10 SendTextAsHardwareKeys: False
 ELSE IF varAnneeConstructionChiffre = (varAnneeConstructionChiffre >= 1975 AND varAnneeConstructionChiffre <= 1981) THEN
 MouseAndKeyboard.SendKeys.FocusAndSendKeys TextToSend: $'''1975-1981''' DelayBetweenKeystrokes: 10 SendTextAsHardwareKeys: False
 ELSE IF varAnneeConstructionChiffre = (varAnneeConstructionChiffre >= 1982 AND varAnneeConstructionChiffre <= 1989) THEN
 MouseAndKeyboard.SendKeys.FocusAndSendKeys TextToSend: $'''1982-1989''' DelayBetweenKeystrokes: 10 SendTextAsHardwareKeys: False
 ELSE IF varAnneeConstructionChiffre = (varAnneeConstructionChiffre >= 1990 AND varAnneeConstructionChiffre <= 1999) THEN
 MouseAndKeyboard.SendKeys.FocusAndSendKeys TextToSend: $'''1990-1999''' DelayBetweenKeystrokes: 10 SendTextAsHardwareKeys: False
 ELSE IF varAnneeConstructionChiffre = (varAnneeConstructionChiffre >= 2000 AND varAnneeConstructionChiffre <= 2005) THEN
 MouseAndKeyboard.SendKeys.FocusAndSendKeys TextToSend: $'''2000-2005''' DelayBetweenKeystrokes: 10 SendTextAsHardwareKeys: False
 ELSE IF varAnneeConstructionChiffre > 2005 THEN
 MouseAndKeyboard.SendKeys.FocusAndSendKeys TextToSend: $'''> 2005''' DelayBetweenKeystrokes: 10 SendTextAsHardwareKeys: False
 END
 LABEL 'Année Construction non convertible en chiffre'
 MouseAndKeyboard.SendKeys.FocusAndSendKeys TextToSend: $'''%varEntree_AnneeConstruction%{Enter}''' DelayBetweenKeystrokes: 10 SendTextAsHardwareKeys: False
 EXIT FUNCTION
END FUNCTION
