 LOOP LoopIndex_OrientationsRestants FROM 1 TO varEntree_NombreOrientations STEP 1
 SWITCH LoopIndex_OrientationsRestants
 CASE = 1
 WebAutomation.Click.Click BrowserInstance: Browser Control: appmask['FormulaireInfosVisite']['Dpdown_InfosVisite_OrientationStatut'] ClickType: WebAutomation.ClickType.LeftClick MouseClick: True WaitForPageToLoadTimeout: 60 MousePositionRelativeToElement: WebAutomation.RectangleEdgePoint.MiddleCenter OffsetX: 0 OffsetY: 0
 MouseAndKeyboard.SendKeys.FocusAndSendKeys TextToSend: $'''%varEntree_StatutOrientation1%{Enter}''' DelayBetweenKeystrokes: 10 SendTextAsHardwareKeys: False
 CASE = 2
 WebAutomation.Click.Click BrowserInstance: Browser Control: appmask['FormulaireInfosVisite']['Dpdown_InfosVisite_OrientationStatut'] ClickType: WebAutomation.ClickType.LeftClick MouseClick: True WaitForPageToLoadTimeout: 60 MousePositionRelativeToElement: WebAutomation.RectangleEdgePoint.MiddleCenter OffsetX: 0 OffsetY: 0
 MouseAndKeyboard.SendKeys.FocusAndSendKeys TextToSend: $'''%varEntree_StatutOrientation2%{Enter}''' DelayBetweenKeystrokes: 10 SendTextAsHardwareKeys: False
 CASE = 3
 WebAutomation.Click.Click BrowserInstance: Browser Control: appmask['FormulaireInfosVisite']['Dpdown_InfosVisite_OrientationStatut'] ClickType: WebAutomation.ClickType.LeftClick MouseClick: True WaitForPageToLoadTimeout: 60 MousePositionRelativeToElement: WebAutomation.RectangleEdgePoint.MiddleCenter OffsetX: 0 OffsetY: 0
 MouseAndKeyboard.SendKeys.FocusAndSendKeys TextToSend: $'''%varEntree_StatutOrientation3%{Enter}''' DelayBetweenKeystrokes: 10 SendTextAsHardwareKeys: False
 CASE = 4
 WebAutomation.Click.Click BrowserInstance: Browser Control: appmask['FormulaireInfosVisite']['Dpdown_InfosVisite_OrientationStatut'] ClickType: WebAutomation.ClickType.LeftClick MouseClick: True WaitForPageToLoadTimeout: 60 MousePositionRelativeToElement: WebAutomation.RectangleEdgePoint.MiddleCenter OffsetX: 0 OffsetY: 0
 MouseAndKeyboard.SendKeys.FocusAndSendKeys TextToSend: $'''%varEntree_StatutOrientation4%{Enter}''' DelayBetweenKeystrokes: 10 SendTextAsHardwareKeys: False
 CASE = 5
 WebAutomation.Click.Click BrowserInstance: Browser Control: appmask['FormulaireInfosVisite']['Dpdown_InfosVisite_OrientationStatut'] ClickType: WebAutomation.ClickType.LeftClick MouseClick: True WaitForPageToLoadTimeout: 60 MousePositionRelativeToElement: WebAutomation.RectangleEdgePoint.MiddleCenter OffsetX: 0 OffsetY: 0
 MouseAndKeyboard.SendKeys.FocusAndSendKeys TextToSend: $'''%varEntree_StatutOrientation5%{Enter}''' DelayBetweenKeystrokes: 10 SendTextAsHardwareKeys: False
