 MouseAndKeyboard.SendKeys.FocusAndSendKeys TextToSend: $'''%varEntree_StatutOrientation6%{Enter}''' DelayBetweenKeystrokes: 10 SendTextAsHardwareKeys: False
 END
 IF LoopIndex_OrientationsRestants <> varEntree_NombreOrientations THEN
 Variables.IncreaseVariable Value: varEntree_IDChampsOrientations IncrementValue: 1
 END
 END
 EXIT FUNCTION
